//! Test support shared by the crates of the workspace (Q1 #101, Q2 #102): paths of the
//! reference data set, the full local data, and golden fingerprints.
//!
//! Included by the tests of each crate with
//!
//! ```ignore
//! #[path = "../../../fixtures/support/mod.rs"]
//! mod fixtures;
//! ```
//!
//! Two categories of real-data tests:
//!
//! - **fixtures** (default, `cargo test --workspace`): read `fixtures/` (versioned,
//!   regenerated by `skimap fixtures`), no network. A missing file fails the test.
//! - **full data** (`#[ignore = "full-data: …"]`, names starting with `full_data_`): read
//!   the complete local data (`$SKIMAP_DATA_DIR`, default `data/`), run by the weekly stage
//!   of the local CI on a fresh `build-all` (`scripts/ci --weekly`; on `data/` as it is:
//!   `scripts/ci --only full-data`) with `cargo test --release
//!   --workspace --features skimap-core/pipeline,skimap-pack/pipeline,skimap-collab/phone
//!   -- --ignored full_data_`. A missing directory fails the test as well.
//!
//!   The weekly build leaves out the sources for personal use only
//!   (`SKIMAP_PERSONAL_SOURCES` unset), so the category has two parts: `full_data_*`
//!   run on any complete data, public or personal, and check what it says it was built
//!   with ([`full_data_personal`]); `full_data_personal_*` need the personal sources
//!   (archived past days, CLPA, the golden figures of a personal build…) and fail on a
//!   public build ([`require_full_data_personal`]). The weekly stage runs the first part
//!   (`--skip full_data_personal_`); `scripts/ci --only full-data` runs both on personal
//!   data, the first part only on public data.
//!
//! Golden fingerprints (Q2): [`golden`].

#![allow(dead_code)]
#![allow(
    clippy::disallowed_methods,
    reason = "tests write their inputs directly"
)]

pub mod french;
pub mod golden;
pub mod privacy;

use std::path::{Path, PathBuf};

/// Root of the reference data set (`fixtures/` at the root of the repository).
pub fn root() -> PathBuf {
    let p = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures");
    p.canonicalize().unwrap_or(p)
}

/// Fails with a clear message when a fixture file is missing.
pub fn require(path: PathBuf) -> PathBuf {
    assert!(
        path.exists(),
        "fixture missing: {} (versioned in fixtures/, regenerated by `skimap fixtures`)",
        path.display()
    );
    path
}

/// Data root of the fixtures, laid out like `data/` (`out/<site>/<layer>/`): give it to
/// `DataLayout::new`.
pub fn data() -> PathBuf {
    require(root().join("data"))
}

/// A layer file of the fixtures: `data/out/<site>/<layer>/<name>`.
pub fn layer_file(site: &str, layer: &str, name: &str) -> PathBuf {
    require(root().join("data/out").join(site).join(layer).join(name))
}

/// A reduced input of the fixtures: `inputs/<rel>`.
pub fn input(rel: &str) -> PathBuf {
    require(root().join("inputs").join(rel))
}

/// Complete local data (`$SKIMAP_DATA_DIR`, default `data/` at the root of the
/// repository), for the full-data tests; fails if it has no `out/` directory.
pub fn full_data() -> PathBuf {
    let root = std::env::var_os("SKIMAP_DATA_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(|| Path::new(env!("CARGO_MANIFEST_DIR")).join("../../data"));
    assert!(
        root.join("out").is_dir(),
        "full-data test: no {}/out (set SKIMAP_DATA_DIR to the complete data, built by `skimap build-all`)",
        root.display()
    );
    root
}

/// Whether the complete local data of `site` was built with the sources for personal
/// use only: `inputs.personal_sources` of `out/<site>/build-all.json`, or, for data built
/// layer by layer (no such record), a source marked `personal_use_only` in one of its
/// layer metadata files (`out/<site>/<layer>/*.meta.json`).
pub fn full_data_personal(site: &str) -> bool {
    let out = full_data().join("out").join(site);
    let read = |p: &Path| -> Option<serde_json::Value> {
        serde_json::from_str(&std::fs::read_to_string(p).ok()?).ok()
    };
    if let Some(flag) = read(&out.join("build-all.json")).and_then(|v| {
        v.pointer("/inputs/personal_sources")
            .and_then(|b| b.as_bool())
    }) {
        return flag;
    }
    let layers = std::fs::read_dir(&out).unwrap_or_else(|e| panic!("{}: {e}", out.display()));
    layers.flatten().any(|layer| {
        std::fs::read_dir(layer.path())
            .into_iter()
            .flatten()
            .flatten()
            .any(|f| {
                f.file_name().to_string_lossy().ends_with(".meta.json")
                    && read(&f.path()).is_some_and(|m| {
                        m["sources"]
                            .as_array()
                            .into_iter()
                            .flatten()
                            .any(|s| s["personal_use_only"] == true)
                    })
            })
    })
}

/// Fails unless the complete local data of `site` was built with the sources for personal
/// use only: the `full_data_personal_*` tests (not run by the weekly build).
pub fn require_full_data_personal(site: &str) {
    assert!(
        full_data_personal(site),
        "{site}: the complete data was built without the sources for personal use only; \
         full_data_personal_ tests need a build with SKIMAP_PERSONAL_SOURCES=1"
    );
}

/// Copies a directory tree (files and subdirectories).
pub fn copy_tree(from: &Path, to: &Path) {
    std::fs::create_dir_all(to).unwrap();
    for e in std::fs::read_dir(from).unwrap_or_else(|e| panic!("{}: {e}", from.display())) {
        let e = e.unwrap();
        let dest = to.join(e.file_name());
        if e.file_type().unwrap().is_dir() {
            copy_tree(&e.path(), &dest);
        } else {
            std::fs::copy(e.path(), &dest).unwrap();
        }
    }
}
